'@ -split "`r?`n") { if ($l) { $ref[$l.Substring(65)] = $l.Substring(0, 64) } }
$bad = 0
foreach ($k in $ref.Keys | Sort-Object) {
    $p = Join-Path $root $k
    if (-not (Test-Path -LiteralPath $p)) { Write-Host "MISSING  $k" -ForegroundColor Yellow; $bad++ }
    elseif ((Get-FileHash -Algorithm SHA256 -LiteralPath $p).Hash -ne $ref[$k]) { Write-Host "CHANGED  $k" -ForegroundColor Red; $bad++ }
}
foreach ($sub in 'vessels','weapons','sensors','aircraft','environment') {
    $d = Join-Path $root $sub
    if (Test-Path -LiteralPath $d) {
        foreach ($f in Get-ChildItem -LiteralPath $d -Recurse -File -Filter '*.txt*') {
            $rel = $f.FullName.Substring($root.Length + 1)
            if (-not $ref.ContainsKey($rel)) { Write-Host "EXTRA    $rel" -ForegroundColor Magenta; $bad++ }
        }
    }
}
Write-Host ''
if ($bad -eq 0) { Write-Host "All $($ref.Count) checked files match DotMod v0.4c." -ForegroundColor Green }
else { Write-Host "$bad difference(s) with DotMod v0.4c in $root" -ForegroundColor Red }
if ($NoPause) { return $bad }
Read-Host 'Enter to close'
